const initial={cash:8420000,energy:82,morale:88,training:0,formation:'4-3-3',players:[
 {name:'Liam Carter',pos:'GK',rating:82,fitness:96,form:8.1,nation:'ENG'}, {name:'Noah Williams',pos:'RB',rating:79,fitness:91,form:7.4,nation:'ENG'}, {name:'Mateo Silva',pos:'CB',rating:84,fitness:94,form:8.0,nation:'BRA'}, {name:'Ethan Brooks',pos:'CB',rating:80,fitness:88,form:7.2,nation:'ENG'}, {name:'Oliver King',pos:'LB',rating:78,fitness:93,form:7.6,nation:'ENG'}, {name:'Lucas Martin',pos:'CM',rating:86,fitness:89,form:8.7,nation:'FRA'}, {name:'Amir Hassan',pos:'CM',rating:81,fitness:92,form:7.9,nation:'MAR'}, {name:'Jack O’Connor',pos:'AM',rating:83,fitness:85,form:8.2,nation:'IRL'}, {name:'Kai Nakamura',pos:'RW',rating:87,fitness:97,form:9.1,nation:'JPN'}, {name:'Rafael Costa',pos:'ST',rating:89,fitness:90,form:9.3,nation:'POR'}, {name:'Theo Bennett',pos:'LW',rating:82,fitness:84,form:7.8,nation:'ENG'}, {name:'Ben Foster',pos:'GK',rating:72,fitness:99,form:6.8,nation:'ENG'}, {name:'Oscar Reed',pos:'CB',rating:74,fitness:93,form:6.9,nation:'ENG'}, {name:'Daniel Kim',pos:'CM',rating:76,fitness:89,form:7.1,nation:'KOR'}, {name:'Mason Clarke',pos:'ST',rating:75,fitness:98,form:7.0,nation:'ENG'}, {name:'Leo Fernandez',pos:'RW',rating:77,fitness:90,form:7.5,nation:'ARG'}, {name:'Harvey Price',pos:'LB',rating:71,fitness:92,form:6.7,nation:'ENG'}, {name:'Samir Patel',pos:'AM',rating:73,fitness:86,form:7.0,nation:'ENG'}, {name:'Finn Murphy',pos:'RB',rating:70,fitness:98,form:6.6,nation:'IRL'}, {name:'Dylan Ward',pos:'CM',rating:72,fitness:95,form:6.9,nation:'ENG'}, {name:'Alex Morgan',pos:'CB',rating:69,fitness:98,form:6.5,nation:'ENG'}, {name:'Victor Santos',pos:'ST',rating:74,fitness:91,form:7.2,nation:'BRA'}, {name:'Charlie Green',pos:'GK',rating:66,fitness:100,form:6.2,nation:'ENG'}],wins:5,draws:1,losses:1,played:7,matchDone:false,facility:1,messages:4};
let game;try{game=JSON.parse(localStorage.getItem('sm26-save'))||initial}catch{game=initial}const save=()=>localStorage.setItem('sm26-save',JSON.stringify(game));const $=s=>document.querySelector(s);const avg=()=>Math.round(game.players.slice(0,11).reduce((a,p)=>a+p.rating,0)/11);let active='overview';
function money(n){return '$'+(n/1e6).toFixed(2)+'M'}function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}
function heading(eyebrow,title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function playerTable(rows){return `<table class="squad-table"><thead><tr><th>PLAYER</th><th>POS</th><th>RATING</th><th>FITNESS</th><th>FORM</th></tr></thead><tbody>${rows.map((p,i)=>`<tr><td><div class="player-cell"><div class="player-avatar">${p.name.split(' ').map(x=>x[0]).join('')}</div>${p.name}</div></td><td><span class="position">${p.pos}</span></td><td><span class="rating ${p.rating<78?'mid':''}">${p.rating}</span></td><td><span class="fitness">● ${p.fitness}%</span></td><td>⭐ ${p.form.toFixed(1)}</td></tr>`).join('')}</tbody></table>`}
function overview(){let form=['W','W','D','W','L','W','W'].slice(-game.played);let score=game.matchDone?`${game.lastScore[0]} <em>–</em> ${game.lastScore[1]}`:'— <em>vs</em> —';return `${heading('TUESDAY, 14 OCTOBER 2025','Good morning, Coach 👋','Here’s what’s happening at Riverside FC today.','<button class="btn btn-primary" data-action="play-match">▶ &nbsp; PLAY NEXT MATCH</button>')}<div class="dash-grid"><div><section class="card"><div class="hero-match"><div class="match-top"><div class="live-tag"><i></i> NEXT FIXTURE</div><div class="match-time">LEAGUE · MATCHDAY 8</div></div><div class="versus"><div class="team"><div class="team-crest">⚡</div><b>Riverside FC</b><small>HOME · ${avg()} OVR</small></div><div class="score">${score}</div><div class="team away"><div class="team-crest">◆</div><b>Westbridge United</b><small>AWAY · 79 OVR</small></div></div><div class="match-bottom"><span>${game.matchDone?'FULL TIME · Match played':'SAT, 18 OCT · 15:00'}</span><button data-view="tactics">⚙ &nbsp; Match preparation</button><strong>${game.matchDone?'3 pts earned':'2 days to match'}</strong></div></div><div class="quick-stats"><div class="quick-stat"><span>LEAGUE POSITION</span><strong>4<small>▲ 2 places</small></strong></div><div class="quick-stat"><span>TEAM RATING</span><strong>${avg()}<small>+2 this week</small></strong></div><div class="quick-stat"><span>TEAM MORALE</span><strong>${game.morale}%<small>Excellent</small></strong></div></div></section><section class="card" style="margin-top:14px"><div class="card-head"><h3>First team</h3><button class="btn btn-light" data-view="squad">Full squad ↗</button></div><div class="table-wrap">${playerTable(game.players.slice(0,5))}</div></section></div><div class="side-stack"><section class="card form-card"><div class="form-title"><h3>Recent form</h3><a href="#" data-view="overview">LEAGUE TABLE ↗</a></div><div class="form-list">${form.map(x=>`<div class="form-result ${x==='D'?'draw':x==='L'?'loss':''}">${x}</div>`).join('')}</div><div class="form-caption"><span>Last 7 league matches</span><b>${game.wins}W ${game.draws}D ${game.losses}L</b></div></section><section class="card news-card"><div class="card-head"><h3>Club updates</h3><span class="subtle">TODAY</span></div><div class="news-item"><div class="news-icon">✦</div><div><b>Training report is ready</b><small>Coach: Team sharpness is looking good.</small></div></div><div class="news-item"><div class="news-icon green">↗</div><div><b>Scouts found 3 prospects</b><small>New talent reports are available.</small></div></div><div class="news-item"><div class="news-icon green">◈</div><div><b>Weekly sponsor payout</b><small>$125,000 added to club balance.</small></div></div></section></div></div><div class="lower-grid"><section class="card"><div class="card-head"><h3>Top performers</h3><span class="subtle">THIS SEASON</span></div><div class="performance-list">${game.players.slice(0,3).sort((a,b)=>b.form-a.form).map((p,i)=>`<div class="performance-row"><span class="rank">0${i+1}</span><div class="player-mini"><div class="mini-face">${p.name.split(' ').map(x=>x[0]).join('')}</div><div><b>${p.name}</b><small>${p.pos} · ${p.rating} OVR</small></div></div><strong>${p.form.toFixed(1)} <span>/ 10</span></strong></div>`).join('')}</div></section><section class="card"><div class="card-head"><h3>Squad condition</h3><span class="subtle">FIRST TEAM</span></div><div style="padding:16px"><div style="display:flex;justify-content:space-between;font-size:10px"><span>Average fitness</span><b>${Math.round(game.players.slice(0,11).reduce((a,p)=>a+p.fitness,0)/11)}%</b></div><div class="progress" style="margin:9px 0 15px"><i style="width:${game.players.slice(0,11).reduce((a,p)=>a+p.fitness,0)/11}%;background:#48a879"></i></div><div style="display:flex;justify-content:space-between;font-size:10px"><span>Team energy</span><b>${game.energy}%</b></div><div class="progress" style="margin:9px 0"><i style="width:${game.energy}%;background:#e8a34c"></i></div></div></section></div>`}
function squad(){return `${heading('YOUR CLUB','First team squad','Manage your 23 players, monitor their condition and build your winning eleven.','<button class="btn btn-light" data-action="rest">☾ &nbsp; REST SQUAD</button>')}<div class="card"><div class="card-head"><h3>Players <span class="subtle">(${game.players.length})</span></h3><span class="subtle">AVERAGE RATING &nbsp; <b style="color:#12845d">${avg()}</b></span></div><div class="table-wrap">${playerTable(game.players)}</div></div><div class="lower-grid"><section class="card"><div class="card-head"><h3>Squad overview</h3></div><div class="quick-stats"><div class="quick-stat"><span>GOALKEEPERS</span><strong>3</strong></div><div class="quick-stat"><span>DEFENDERS</span><strong>7</strong></div><div class="quick-stat"><span>MIDFIELDERS</span><strong>7</strong></div></div></section><section class="card"><div class="card-head"><h3>Player of the month</h3></div><div class="performance-list"><div class="performance-row"><div class="mini-face">RC</div><div class="player-mini"><b>Rafael Costa</b><small>Striker · 6 goals this season</small></div><strong>89 <span>OVR</span></strong></div></div></section></div>`}
function tactics(){const positions=game.formation==='4-4-2'?[[50,85],[16,65],[39,70],[61,70],[84,65],[20,42],[40,48],[60,48],[80,42],[38,20],[62,20]]:game.formation==='3-5-2'?[[50,85],[25,68],[50,72],[75,68],[12,45],[32,50],[50,42],[68,50],[88,45],[38,20],[62,20]]:[[50,85],[15,66],[39,70],[61,70],[85,66],[28,48],[50,53],[72,48],[16,23],[50,18],[84,23]];let starters=game.players.slice(0,11);return `${heading('MATCH PREPARATION','Tactics & formation','Set your shape, pick your starting XI and get the squad match-ready.','<button class="btn btn-primary" data-action="save-tactics">✓ &nbsp; SAVE TACTICS</button>')}<div class="dash-grid"><section class="card"><div class="card-head"><h3>Formation</h3><select id="formation" class="btn btn-light">${['4-3-3','4-4-2','3-5-2'].map(f=>`<option ${game.formation===f?'selected':''}>${f}</option>`).join('')}</select></div><div class="pitch"><div class="pitch-lines"><i class="half"></i><i class="center-circle"></i><i class="box top"></i><i class="box bottom"></i><i class="goal top"></i><i class="goal bottom"></i></div>${positions.map((pt,i)=>`<div class="pitch-player" style="left:${pt[0]}%;top:${pt[1]}%"><span>${starters[i].name.split(' ').map(x=>x[0]).join('')}</span><small>${starters[i].name.split(' ')[1]}</small></div>`).join('')}</div><div class="quick-stats"><div class="quick-stat"><span>MENTALITY</span><strong><select id="mentality" class="small-select"><option>Balanced</option><option>Attacking</option><option>Defensive</option></select></strong></div><div class="quick-stat"><span>TEAM RATING</span><strong>${avg()}</strong></div><div class="quick-stat"><span>CHEMISTRY</span><strong>92%</strong></div></div></section><div><section class="card"><div class="card-head"><h3>Match plan</h3></div><div class="settings">${[['Passing style','Short passing'],['Tempo','High tempo'],['Pressing','High press'],['Tackling','Normal']].map(([a,b])=>`<label>${a}<select><option>${b}</option><option>${a==='Tempo'?'Low tempo':'Balanced'}</option><option>${a==='Pressing'?'Low block':'Aggressive'}</option></select></label>`).join('')}</div></section><section class="card" style="margin-top:15px"><div class="card-head"><h3>Team talk</h3></div><div class="talk-options"><button data-action="talk" data-talk="motivate">💪 &nbsp; Motivate players</button><button data-action="talk" data-talk="calm">🧠 &nbsp; Keep them calm</button></div></section></div></div>`}
function training(){return `${heading('PLAYER DEVELOPMENT','Training ground','Develop your players and sharpen your squad before matchday.','<button class="btn btn-primary" data-action="training">✦ &nbsp; START TRAINING</button>')}<div class="dash-grid"><section class="card"><div class="card-head"><h3>Training programmes</h3><span class="subtle">${game.training} SESSIONS THIS WEEK</span></div><div class="training-list">${[['⚽','Attacking patterns','Finishing · Movement · Creativity','+ Shooting'],['◉','Defensive shape','Positioning · Tackling · Awareness','+ Defending'],['⌁','Possession & passing','Passing · Ball control · Vision','+ Passing'],['↗','Fitness & conditioning','Stamina · Strength · Recovery','+ Fitness']].map((x,i)=>`<div class="training-item"><div class="training-icon">${x[0]}</div><div class="training-info"><b>${x[1]}</b><small>${x[2]}</small></div><span class="gain">${x[3]}</span><button class="btn btn-light" data-action="training" data-training="${i}">Train</button></div>`).join('')}</div></section><section class="card"><div class="card-head"><h3>Training condition</h3></div><div class="condition"><div class="condition-number">${game.energy}<small>%</small></div><b>Squad energy</b><p>Your players have good energy for a full training session.</p><div class="progress"><i style="width:${game.energy}%;background:#4baf7a"></i></div><button class="btn btn-light" data-action="rest">☾ &nbsp; Give squad a rest</button></div></section></div><section class="card" style="margin-top:16px"><div class="card-head"><h3>Recommended focus</h3><span class="subtle">BASED ON UPCOMING OPPONENT</span></div><div class="quick-stats"><div class="quick-stat"><span>OPPONENT WEAKNESS</span><strong>Central defence</strong></div><div class="quick-stat"><span>BEST SESSION</span><strong>Attacking patterns</strong></div><div class="quick-stat"><span>EXPECTED BOOST</span><strong>+2% sharpness</strong></div></div></section>`}
function transfers(){return `${heading('SCOUTING NETWORK','Transfer market','Discover talent and strengthen your squad for the season ahead.','<button class="btn btn-light" data-action="scout">⌕ &nbsp; SCOUT FOR PLAYERS</button>')}<div class="card"><div class="card-head"><h3>Recommended players</h3><span class="subtle">3 SCOUT REPORTS</span></div><div class="table-wrap"><table class="squad-table"><thead><tr><th>PLAYER</th><th>AGE</th><th>POSITION</th><th>RATING</th><th>VALUE</th><th></th></tr></thead><tbody>${[['Marco Bellini','21','ST','81','$3.2M','🇮🇹'],['Jude Okafor','19','CM','78','$2.1M','🇳🇬'],['André Moreau','24','CB','83','$4.5M','🇫🇷']].map((p,i)=>`<tr><td><div class="player-cell"><div class="player-avatar">${p[0].split(' ').map(x=>x[0]).join('')}</div>${p[0]} <small>${p[5]}</small></div></td><td>${p[1]}</td><td>${p[2]}</td><td><span class="rating">${p[3]}</span></td><td>${p[4]}</td><td><button class="btn btn-primary" data-action="buy" data-index="${i}">Sign player</button></td></tr>`).join('')}</tbody></table></div></div><div class="lower-grid"><section class="card"><div class="card-head"><h3>Transfer strategy</h3></div><div style="padding:16px;font-size:11px;color:#7e8a83;line-height:1.7">Your scouting team recommends adding depth at striker and central defence. You have a healthy transfer budget and room to invest in young talent.</div></section><section class="card"><div class="card-head"><h3>Transfer budget</h3></div><div class="quick-stats"><div class="quick-stat"><span>AVAILABLE</span><strong>${money(game.cash)}</strong></div><div class="quick-stat"><span>WAGE ROOM</span><strong>$84K<span style="font:9px 'DM Sans'">/wk</span></strong></div></div></section></div>`}
function facilities(){return `${heading('CLUB DEVELOPMENT','Club facilities','Invest in your infrastructure to improve player growth and matchday income.','<button class="btn btn-primary" data-action="upgrade">↑ &nbsp; UPGRADE FACILITY</button>')}<div class="dash-grid">${[['🏟','Riverside Stadium','Capacity · 32,500','Matchday revenue +$125K / home match'],['⚽','Training Centre','Player development · Level '+game.facility,'Training gains '+(game.facility*2)+'% faster'],['✚','Medical Centre','Recovery · Level 2','Injuries heal 15% faster'],['♧','Youth Academy','Prospect pipeline · Level 3','New academy player each season']].map((a,i)=>`<section class="card facility-card"><div class="facility-art">${a[0]}</div><div class="facility-body"><div class="eyebrow">${i===0?'MATCHDAY':i===1?'PLAYER DEVELOPMENT':i===2?'SQUAD HEALTH':'YOUTH DEVELOPMENT'}</div><h3>${a[1]}</h3><p>${a[2]}</p><small>${a[3]}</small><button class="btn btn-light" data-action="${i===1?'upgrade':'facility'}">${i===1?'Upgrade · '+money(1500000):'View facility'}</button></div></section>`).join('')}</div>`}
function finance(){return `${heading('CLUB OPERATIONS','Finances','A clear picture of Riverside FC’s financial health.')}<div class="quick-stats card"><div class="quick-stat"><span>CLUB BALANCE</span><strong>${money(game.cash)}</strong></div><div class="quick-stat"><span>WEEKLY INCOME</span><strong style="color:#32945e">+$325K</strong></div><div class="quick-stat"><span>WEEKLY EXPENSES</span><strong style="color:#d4805e">−$200K</strong></div></div><div class="lower-grid"><section class="card"><div class="card-head"><h3>Recent transactions</h3><span class="subtle">THIS WEEK</span></div>${[['Sponsor payment','+$125,000','green'],['Matchday ticket sales','+$200,000','green'],['Player wages','−$200,000','red'],['Facility maintenance','−$35,000','red']].map(x=>`<div class="news-item"><div class="news-icon ${x[2]==='green'?'green':''}">◈</div><div style="flex:1"><b>${x[0]}</b><small>14 October 2025</small></div><b style="color:${x[2]==='green'?'#32945e':'#d4805e'}">${x[1]}</b></div>`).join('')}</section><section class="card"><div class="card-head"><h3>Revenue breakdown</h3></div><div class="condition"><div class="finance-bar"><span>Commercial</span><i><b style="width:75%"></b></i><strong>$180K</strong></div><div class="finance-bar"><span>Matchday</span><i><b style="width:54%"></b></i><strong>$120K</strong></div><div class="finance-bar"><span>Broadcast</span><i><b style="width:35%"></b></i><strong>$85K</strong></div></div></section></div>`}
function inbox(){return `${heading('CLUB COMMUNICATIONS','Inbox','Stay up to date with the latest from your club.','<button class="btn btn-light" data-action="read-all">✓ &nbsp; MARK ALL READ</button>')}<section class="card">${[['⚽','Training report — squad sharpness is up','Coach: The players looked focused and sharp in today’s session. The team is ready for the next fixture.','10:24 · TRAINING'],['↗','Three new scouting reports','Your scouting network has identified three promising players for the first team.','09:12 · SCOUTING'],['◈','Weekly sponsor payment received','$125,000 has been added to the club balance. Keep up the great work!','YESTERDAY · FINANCE'],['⚕','Fitness update: Liam Carter','Liam Carter is back to 96% fitness after a light recovery session.','YESTERDAY · MEDICAL']].map(x=>`<div class="message"><div class="news-icon green">${x[0]}</div><div><b>${x[1]}</b><p>${x[2]}</p><small>${x[3]}</small></div></div>`).join('')}</section>`}
const views={overview,squad,tactics,training,transfers,facilities,finance,inbox};function render(view=active){active=view;$('#page-title').textContent=view.toUpperCase();document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===view));$('#view-container').innerHTML=views[view]();$('#cash').textContent=money(game.cash);save()}
function simulate(){if(game.matchDone){toast('You’ve already played this matchday!');return}const strength=avg()+Math.round(game.morale/15)+Math.round(game.energy/20);let goals=Math.max(0,Math.floor(Math.random()*4+(strength-80)/13));let opp=Math.max(0,Math.floor(Math.random()*3+(79-strength)/15));if(goals===opp)opp++;game.lastScore=[goals,opp];game.matchDone=true;game.played++;if(goals>opp){game.wins++;game.cash+=200000;game.morale=Math.min(100,game.morale+5);game.players.slice(0,11).forEach(p=>p.form=Math.min(10,p.form+.2))}else if(goals===opp){game.draws++;game.cash+=100000;game.morale=Math.min(100,game.morale+1)}else{game.losses++;game.morale=Math.max(40,game.morale-6)}game.energy=Math.max(35,game.energy-18);render('overview');toast(`Full time: Riverside ${goals} – ${opp} Westbridge`)}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){e.preventDefault();render(nav.dataset.view);return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='play-match')simulate();if(a==='save-tactics'){game.formation=$('#formation').value;toast('Tactics saved. Your team is ready!');save()}if(a==='training'){if(game.energy<20){toast('Squad energy is too low. Give them a rest first.');return}const ix=Number(b.dataset.training||0);const targets=game.players.slice(ix===0?8:ix===1?1:ix===2?5:0,ix===0?11:ix===1?5:ix===2?8:11);targets.forEach(p=>{p.rating=Math.min(99,p.rating+(Math.random()>.65?1:0));p.form=Math.min(10,+(p.form+.1).toFixed(1));p.fitness=Math.max(60,p.fitness-(ix===3?4:8))});game.energy=Math.max(10,game.energy-14);game.training++;save();render('training');toast('Great session! Player skills and sharpness improved.')}if(a==='rest'){game.players.forEach(p=>p.fitness=Math.min(100,p.fitness+9));game.energy=Math.min(100,game.energy+24);game.morale=Math.min(100,game.morale+2);save();render(active);toast('The squad has rested and recovered.')}if(a==='talk'){game.morale=Math.min(100,game.morale+(b.dataset.talk==='motivate'?7:3));save();render('tactics');toast('Team talk complete. Morale is now '+game.morale+'%.')}if(a==='buy'){const data=[['Marco Bellini','ST',81,3200000,'ITA'],['Jude Okafor','CM',78,2100000,'NGA'],['André Moreau','CB',83,4500000,'FRA']][Number(b.dataset.index)];if(game.cash<data[3]){toast('Not enough funds for this transfer.');return}if(game.players.length>=28){toast('Your squad is full. Release a player first.');return}game.cash-=data[3];game.players.push({name:data[0],pos:data[1],rating:data[2],fitness:100,form:7.5,nation:data[4]});save();render('transfers');toast(`${data[0]} signed for Riverside FC!`)}if(a==='scout')toast('Scouts are working on fresh player reports!');if(a==='upgrade'){if(game.cash<1500000){toast('Not enough funds to upgrade this facility.');return}game.cash-=1500000;game.facility++;save();render('facilities');toast('Training Centre upgraded to level '+game.facility+'!')}if(a==='facility')toast('Facility operations are running smoothly.');if(a==='read-all'){game.messages=0;toast('You’re all caught up!')}});document.addEventListener('change',e=>{if(e.target.id==='formation'){game.formation=e.target.value;render('tactics')}});render();

